(30890, 'Joshua 8:13', 'Joshua', 8, 13, 'عسکر د جګړې دپاره تیار کړای شول. اصلي کمپ د ښار په شمال کې ؤ او پاتې کسان په لوېدیځ کې وو. یوشع شپه په دره کې تېره کړه.', 'عسکر د جګرې دپاره تیار کرای شول. اصلی کمپ د شار په شمال کې و او پاتې کسان په لوېدیج کې وو. یوشع شپه په دره کې تېره کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30891, 'Joshua 8:14', 'Joshua', 8, 14, 'کله چې د عای پاچا د یوشع کسان ولیدل، نو هغه زر لاس په کار شو. هغه د خپلو ټولو کسانو سره د اردن د درې خواته روان شو چې هلته د اسراییلیانو سره وجنګیږي، خو هغه نه پوهېده چې د شا له خوا به ورباندې حمله وشي.', 'کله چې د عای پاچا د یوشع کسان ولیدل، نو هغه زر لاس په کار شو. هغه د خپلو تولو کسانو سره د اردن د درې خواته روان شو چې هلته د اسراییلیانو سره وجنګیزی، خو هغه نه پوهېده چې د شا له خوا به ورباندې حمله وشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30892, 'Joshua 8:15', 'Joshua', 8, 15, 'یوشع د خپلو کسانو سره داسې وښودله چې ګوندې هغوی په شا شول او د دښتې خواته وتښتېدل.', 'یوشع د خپلو کسانو سره داسې وشودله چې ګوندې هغوی په شا شول او د دشتې خواته وتشتېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30893, 'Joshua 8:16', 'Joshua', 8, 16, 'د ښار په ټولو خلکو باندې غږ وشو چې په اسراییلیانو پسې روان شي. څنګه چې د عای خلک په هغوی پسې لاړل، نو اسراییلیانو هغوی وغولول او د ښار څخه یې لېرې کړل.', 'د شار په تولو خلکو باندې غز وشو چې په اسراییلیانو پسې روان شی. چنګه چې د عای خلک په هغوی پسې لارل، نو اسراییلیانو هغوی وغولول او د شار چخه یې لېرې کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30894, 'Joshua 8:17', 'Joshua', 8, 17, 'په عای یا بیت ییل کې چې هرڅوک ؤ هغه ټول په اسراییلیانو پسې روان شول. هلته هېڅوک پاتې نه شو چې د ښار څخه دفاع وکړي او د ښار دروازې خلاصې پاتې شوې.', 'په عای یا بیت ییل کې چې هرچوک و هغه تول په اسراییلیانو پسې روان شول. هلته هېچوک پاتې نه شو چې د شار چخه دفاع وکری او د شار دروازې خلاصې پاتې شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30895, 'Joshua 8:18', 'Joshua', 8, 18, 'بیا څښتن یوشع ته وویل: «خپله نېزه د عای خواته ونیسه، ځکه چې هغه تاته درکوم.» نو څنګه چې یوشع ته ویل شوي وو هغه هماغسې وکړل', 'بیا چشتن یوشع ته وویل: «خپله نېزه د عای خواته ونیسه، جکه چې هغه تاته درکوم.» نو چنګه چې یوشع ته ویل شوی وو هغه هماغسې وکرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30896, 'Joshua 8:19', 'Joshua', 8, 19, 'او څنګه چې هغه خپله نېزه پورته کړه، کوم کسان چې پټ وو هغوی زر د خپلو ځایونو څخه پاڅېدل، ښار ته په منډه ورننوتل او هغه یې ونیوه. هغوی سمدلاسه ښار ته اور واچاوه.', 'او چنګه چې هغه خپله نېزه پورته کره، کوم کسان چې پت وو هغوی زر د خپلو جایونو چخه پاچېدل، شار ته په منده ورننوتل او هغه یې ونیوه. هغوی سمدلاسه شار ته اور واچاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30897, 'Joshua 8:22', 'Joshua', 8, 22, 'نو هغه اسراییلیان چې په ښار کې وو په جګړه کې د برخې اخیستلو دپاره راښکته شول. نو د عای خلکو ولیدل چې اسراییلیانو هغوی بیخي کلابند کړي دي او هغوی ټول ووژل شول. هېڅوک ونه تښتېده او نه څوک ژوندی پاتې شو،', 'نو هغه اسراییلیان چې په شار کې وو په جګره کې د برخې اخیستلو دپاره راشکته شول. نو د عای خلکو ولیدل چې اسراییلیانو هغوی بیخی کلابند کری دی او هغوی تول ووژل شول. هېچوک ونه تشتېده او نه چوک ژوندی پاتې شو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_8_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
